import { useState, useEffect, useMemo } from "react";
import {
  CalendarCheck,
  BarChart3,
  ClipboardList,
  LogOut,
  Plus,
  Trash2,
  Check,
  X,
  AlertTriangle,
  Loader2,
} from "lucide-react";

// ---------------------------------------------------------------------------
// Theme — dark corner-of-the-gym palette: charcoal canvas, ring-rope red,
// canvas-tape parchment for text, olive for "presente", brass for stats.
// ---------------------------------------------------------------------------
const C = {
  bg: "#141310",
  bgPanel: "#1C1A16",
  bgRaised: "#242119",
  line: "#39352C",
  lineSoft: "#2A271F",
  text: "#EDE6D6",
  textDim: "#A79E8C",
  textFaint: "#6E6858",
  red: "#B8272B",
  redDim: "#7A2224",
  olive: "#5C6B45",
  oliveBright: "#7C8F58",
  brass: "#BB8C43",
};

const LOGO = "data:image/jpeg;base64,";

const PERIODS = ["Manhã", "Tarde", "Noite"];

function uid() {
  return Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
}
function todayISO() {
  const d = new Date();
  return d.toISOString().slice(0, 10);
}
function fmtDate(iso) {
  if (!iso) return "";
  const [y, m, d] = iso.split("-");
  return `${d}/${m}/${y}`;
}

const SHARED_PASSWORD = "teamonan2026";

export default function TeamOnanPresenca() {
  const [booted, setBooted] = useState(false);
  const [authed, setAuthed] = useState(false);
  const [pwInput, setPwInput] = useState("");
  const [pwError, setPwError] = useState("");

  const [page, setPage] = useState("presenca");

  const [units, setUnits] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [students, setStudents] = useState([]);
  const [classes, setClasses] = useState([]);
  const [attendance, setAttendance] = useState([]);
  const [storageError, setStorageError] = useState("");

  // ---- load persisted data -------------------------------------------------
  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get("onan-cadastros", true);
        const data = res ? JSON.parse(res.value) : null;
        if (data) {
          setUnits(data.units || []);
          setTeachers(data.teachers || []);
          setStudents(data.students || []);
        }
      } catch (e) {
        // key doesn't exist yet — start empty
      }
      try {
        const res2 = await window.storage.get("onan-registro", true);
        const data2 = res2 ? JSON.parse(res2.value) : null;
        if (data2) {
          setClasses(data2.classes || []);
          setAttendance(data2.attendance || []);
        }
      } catch (e) {
        // key doesn't exist yet — start empty
      }
      setBooted(true);
    })();
  }, []);

  async function persistCadastros(u, t, s) {
    try {
      await window.storage.set(
        "onan-cadastros",
        JSON.stringify({ units: u, teachers: t, students: s }),
        true
      );
      setStorageError("");
    } catch (e) {
      setStorageError("Não consegui salvar os cadastros agora. Tente de novo.");
    }
  }

  async function persistRegistro(c, a) {
    try {
      await window.storage.set(
        "onan-registro",
        JSON.stringify({ classes: c, attendance: a }),
        true
      );
      setStorageError("");
    } catch (e) {
      setStorageError("Não consegui salvar a presença agora. Tente de novo.");
    }
  }

  // ---- login ---------------------------------------------------------------
  function handleLogin(e) {
    e.preventDefault();
    if (pwInput === SHARED_PASSWORD) {
      setAuthed(true);
      setPwError("");
    } else {
      setPwError("Senha incorreta.");
    }
  }

  if (!booted) {
    return (
      <div
        style={{ background: C.bg, color: C.textDim }}
        className="w-full min-h-screen flex items-center justify-center gap-2 text-sm"
      >
        <Loader2 className="animate-spin" size={18} />
        Carregando...
      </div>
    );
  }

  if (!authed) {
    return (
      <div
        style={{ background: C.bg }}
        className="w-full min-h-screen flex items-center justify-center p-6"
      >
        <form
          onSubmit={handleLogin}
          style={{ background: C.bgPanel, borderColor: C.line }}
          className="w-full max-w-sm border rounded-md p-8 flex flex-col gap-5"
        >
          <div className="flex flex-col items-center gap-3 mb-2">
            <img
              src={LOGO}
              alt="Team Onan"
              style={{ border: `2px solid ${C.red}` }}
              className="w-16 h-16 rounded-full object-cover"
            />
            <div className="text-center">
              <div style={{ color: C.text }} className="font-bold text-lg tracking-tight">
                Team Onan
              </div>
            </div>
          </div>
          <label className="flex flex-col gap-1.5">
            <span style={{ color: C.textDim }} className="text-xs">
              Senha de acesso
            </span>
            <input
              type="password"
              value={pwInput}
              onChange={(e) => setPwInput(e.target.value)}
              style={{ background: C.bgRaised, borderColor: C.line, color: C.text }}
              className="border rounded-md px-3 py-2 text-sm outline-none focus:ring-1"
              autoFocus
            />
          </label>
          {pwError && (
            <div style={{ color: C.red }} className="text-xs -mt-2">
              {pwError}
            </div>
          )}
          <button
            type="submit"
            style={{ background: C.red, color: C.text }}
            className="rounded-md py-2 text-sm font-semibold"
          >
            Entrar
          </button>
        </form>
      </div>
    );
  }

  return (
    <div style={{ background: C.bg }} className="w-full min-h-screen flex flex-col">
      {/* top bar */}
      <div
        style={{ background: C.bgPanel, borderColor: C.line }}
        className="border-b flex items-center justify-between px-4 py-3 sm:px-6"
      >
        <div className="flex items-center gap-2.5">
          <img
            src={LOGO}
            alt="Team Onan"
            style={{ border: `1.5px solid ${C.red}` }}
            className="w-9 h-9 rounded-full object-cover shrink-0"
          />
          <div style={{ color: C.text }} className="font-bold tracking-tight text-sm sm:text-base">
            Team Onan
          </div>
        </div>
        <button
          onClick={() => setAuthed(false)}
          style={{ color: C.textDim }}
          className="flex items-center gap-1.5 text-xs hover:opacity-80"
        >
          <LogOut size={14} />
          Sair
        </button>
      </div>

      {/* nav */}
      <div style={{ borderColor: C.line }} className="border-b flex px-2 sm:px-6">
        <NavTab active={page === "presenca"} onClick={() => setPage("presenca")} icon={CalendarCheck}>
          Presença
        </NavTab>
        <NavTab active={page === "dashboard"} onClick={() => setPage("dashboard")} icon={BarChart3}>
          Dashboard
        </NavTab>
        <NavTab active={page === "cadastros"} onClick={() => setPage("cadastros")} icon={ClipboardList}>
          Cadastros
        </NavTab>
      </div>

      {storageError && (
        <div style={{ background: C.redDim, color: C.text }} className="text-xs px-4 py-2 text-center">
          {storageError}
        </div>
      )}

      <div className="flex-1 p-4 sm:p-6">
        {page === "presenca" && (
          <PresencaPage
            units={units}
            teachers={teachers}
            students={students}
            classes={classes}
            setClasses={setClasses}
            attendance={attendance}
            setAttendance={setAttendance}
            persistRegistro={persistRegistro}
          />
        )}
        {page === "dashboard" && (
          <DashboardPage
            units={units}
            teachers={teachers}
            students={students}
            classes={classes}
            attendance={attendance}
          />
        )}
        {page === "cadastros" && (
          <CadastrosPage
            units={units}
            setUnits={setUnits}
            teachers={teachers}
            setTeachers={setTeachers}
            students={students}
            setStudents={setStudents}
            persistCadastros={persistCadastros}
          />
        )}
      </div>
    </div>
  );
}

function NavTab({ active, onClick, icon: Icon, children }) {
  return (
    <button
      onClick={onClick}
      style={{
        color: active ? C.text : C.textFaint,
        borderColor: active ? C.red : "transparent",
      }}
      className="flex items-center gap-1.5 text-xs sm:text-sm px-3 sm:px-4 py-3 border-b-2 -mb-px font-medium"
    >
      <Icon size={15} />
      {children}
    </button>
  );
}

function Select({ value, onChange, options, placeholder, disabled }) {
  return (
    <select
      value={value}
      disabled={disabled}
      onChange={(e) => onChange(e.target.value)}
      style={{
        background: C.bgRaised,
        borderColor: C.line,
        color: value ? C.text : C.textFaint,
        opacity: disabled ? 0.5 : 1,
      }}
      className="border rounded-md px-3 py-2 text-sm outline-none w-full"
    >
      <option value="">{placeholder}</option>
      {options.map((o) => (
        <option key={o.value} value={o.value}>
          {o.label}
        </option>
      ))}
    </select>
  );
}

// ---------------------------------------------------------------------------
// Presença
// ---------------------------------------------------------------------------
function PresencaPage({
  units,
  teachers,
  students,
  classes,
  setClasses,
  attendance,
  setAttendance,
  persistRegistro,
}) {
  const [selUnit, setSelUnit] = useState("");
  const [selPeriod, setSelPeriod] = useState("");
  const [selTeacher, setSelTeacher] = useState("");
  const [selDate, setSelDate] = useState(todayISO());
  const [popup, setPopup] = useState(null);

  const ready = selUnit && selPeriod && selTeacher && selDate;

  const currentClass = classes.find(
    (c) =>
      c.unitId === selUnit &&
      c.period === selPeriod &&
      c.teacherId === selTeacher &&
      c.date === selDate
  );

  const roster = students.filter((s) => s.unitId === selUnit);

  function isChecked(studentId) {
    if (!currentClass) return false;
    return attendance.some(
      (a) => a.classId === currentClass.id && a.studentId === studentId
    );
  }

  function toggleAttendance(studentId, studentName) {
    if (!ready) return;

    // conflict: same student, same date + period, different class already logged
    const conflict = attendance.find((a) => {
      if (a.studentId !== studentId) return false;
      const cls = classes.find((c) => c.id === a.classId);
      if (!cls) return false;
      if (cls.date !== selDate || cls.period !== selPeriod) return false;
      if (currentClass && cls.id === currentClass.id) return false;
      return true;
    });

    if (conflict) {
      const cls = classes.find((c) => c.id === conflict.classId);
      const teacherName = teachers.find((t) => t.id === cls.teacherId)?.name || "—";
      const unitName = units.find((u) => u.id === cls.unitId)?.name || "—";
      setPopup({ studentName, teacherName, unitName });
      return;
    }

    // uncheck within the same class
    if (currentClass) {
      const existing = attendance.find(
        (a) => a.classId === currentClass.id && a.studentId === studentId
      );
      if (existing) {
        const next = attendance.filter((a) => a.id !== existing.id);
        setAttendance(next);
        persistRegistro(classes, next);
        return;
      }
    }

    // create class record if this is the first check for this combo
    let nextClasses = classes;
    let classId = currentClass?.id;
    if (!classId) {
      classId = uid();
      nextClasses = [
        ...classes,
        { id: classId, unitId: selUnit, period: selPeriod, teacherId: selTeacher, date: selDate },
      ];
      setClasses(nextClasses);
    }
    const nextAttendance = [...attendance, { id: uid(), classId, studentId }];
    setAttendance(nextAttendance);
    persistRegistro(nextClasses, nextAttendance);
  }

  const checkedCount = currentClass
    ? attendance.filter((a) => a.classId === currentClass.id).length
    : 0;

  return (
    <div className="max-w-2xl">
      <div
        style={{ background: C.bgPanel, borderColor: C.line }}
        className="border rounded-md p-4 sm:p-5 grid grid-cols-2 gap-3 mb-5"
      >
        <div className="col-span-2 sm:col-span-1">
          <FieldLabel>Unidade</FieldLabel>
          <Select
            value={selUnit}
            onChange={setSelUnit}
            placeholder="Selecione a unidade"
            options={units.map((u) => ({ value: u.id, label: u.name }))}
          />
        </div>
        <div className="col-span-2 sm:col-span-1">
          <FieldLabel>Período</FieldLabel>
          <Select
            value={selPeriod}
            onChange={setSelPeriod}
            placeholder="Manhã ou noite"
            options={PERIODS.map((p) => ({ value: p, label: p }))}
          />
        </div>
        <div className="col-span-2 sm:col-span-1">
          <FieldLabel>Professor</FieldLabel>
          <Select
            value={selTeacher}
            onChange={setSelTeacher}
            placeholder="Selecione o professor"
            options={teachers.map((t) => ({ value: t.id, label: t.name }))}
          />
        </div>
        <div className="col-span-2 sm:col-span-1">
          <FieldLabel>Data</FieldLabel>
          <input
            type="date"
            value={selDate}
            onChange={(e) => setSelDate(e.target.value)}
            style={{ background: C.bgRaised, borderColor: C.line, color: C.text }}
            className="border rounded-md px-3 py-2 text-sm outline-none w-full"
          />
        </div>
      </div>

      {!ready && (
        <EmptyState text="Selecione unidade, período, professor e data para abrir a lista de alunos." />
      )}

      {ready && roster.length === 0 && (
        <EmptyState text="Nenhum aluno cadastrado nessa unidade ainda. Cadastre em Cadastros." />
      )}

      {ready && roster.length > 0 && (
        <div style={{ background: C.bgPanel, borderColor: C.line }} className="border rounded-md overflow-hidden">
          <div
            style={{ borderColor: C.lineSoft, color: C.textDim }}
            className="border-b px-4 py-2.5 flex items-center justify-between text-xs"
          >
            <span>
              {fmtDate(selDate)} · {selPeriod}
            </span>
            <span style={{ color: C.oliveBright }} className="font-semibold">
              {checkedCount}/{roster.length} presentes
            </span>
          </div>
          <table className="w-full text-sm">
            <thead>
              <tr style={{ color: C.textFaint, borderColor: C.lineSoft }} className="border-b text-left text-xs">
                <th className="font-medium px-4 py-2">Aluno</th>
                <th className="font-medium px-4 py-2 w-28 text-center">Presença</th>
              </tr>
            </thead>
            <tbody>
              {roster.map((s) => {
                const checked = isChecked(s.id);
                return (
                  <tr key={s.id} style={{ borderColor: C.lineSoft }} className="border-b last:border-0">
                    <td style={{ color: C.text }} className="px-4 py-2.5">
                      {s.name}
                    </td>
                    <td className="px-4 py-2.5">
                      <div className="flex justify-center">
                        <button
                          onClick={() => toggleAttendance(s.id, s.name)}
                          style={{
                            background: checked ? C.olive : "transparent",
                            borderColor: checked ? C.olive : C.line,
                          }}
                          className="w-8 h-8 rounded-md border flex items-center justify-center"
                          aria-label={`Marcar presença de ${s.name}`}
                        >
                          {checked && <Check size={16} color={C.text} />}
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {popup && (
        <Modal onClose={() => setPopup(null)}>
          <div className="flex flex-col items-center text-center gap-3 p-2">
            <div
              style={{ background: C.redDim }}
              className="w-11 h-11 rounded-full flex items-center justify-center"
            >
              <AlertTriangle size={20} color={C.text} />
            </div>
            <div style={{ color: C.text }} className="font-semibold">
              Presença já confirmada
            </div>
            <div style={{ color: C.textDim }} className="text-sm leading-relaxed">
              {popup.studentName} já foi marcado presente hoje no período da{" "}
              {selPeriod.toLowerCase()}, com o professor {popup.teacherName} ({popup.unitName}).
            </div>
            <button
              onClick={() => setPopup(null)}
              style={{ background: C.red, color: C.text }}
              className="mt-1 rounded-md px-4 py-2 text-sm font-semibold w-full"
            >
              Entendi
            </button>
          </div>
        </Modal>
      )}
    </div>
  );
}

function FieldLabel({ children }) {
  return (
    <div style={{ color: C.textDim }} className="text-xs mb-1.5">
      {children}
    </div>
  );
}

function EmptyState({ text }) {
  return (
    <div
      style={{ background: C.bgPanel, borderColor: C.line, color: C.textFaint }}
      className="border border-dashed rounded-md p-8 text-center text-sm"
    >
      {text}
    </div>
  );
}

function Modal({ children, onClose }) {
  return (
    <div
      onClick={onClose}
      style={{ background: "rgba(0,0,0,0.6)" }}
      className="fixed inset-0 flex items-center justify-center p-4 z-50"
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{ background: C.bgPanel, borderColor: C.line }}
        className="border rounded-md max-w-sm w-full p-5"
      >
        {children}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Dashboard
// ---------------------------------------------------------------------------
function DashboardPage({ units, teachers, students, classes, attendance }) {
  const [mesAno, setMesAno] = useState("");
  const [unitId, setUnitId] = useState("");
  const [teacherId, setTeacherId] = useState("");
  const [studentId, setStudentId] = useState("");

  const hasFilters = mesAno || unitId || teacherId || studentId;

  const studentOptions = unitId ? students.filter((s) => s.unitId === unitId) : students;

  const scopeClasses = classes.filter(
    (c) =>
      (!mesAno || c.date.slice(0, 7) === mesAno) &&
      (!unitId || c.unitId === unitId) &&
      (!teacherId || c.teacherId === teacherId)
  );
  const scopeClassIds = new Set(scopeClasses.map((c) => c.id));
  const scopeAttendance = attendance.filter(
    (a) => scopeClassIds.has(a.classId) && (!studentId || a.studentId === studentId)
  );

  const totalAulas = scopeClasses.length;
  const totalPresencas = scopeAttendance.length;
  const mediaPorAula = totalAulas ? (totalPresencas / totalAulas).toFixed(1) : "0";

  const unitsInScope = unitId ? units.filter((u) => u.id === unitId) : units;
  const porUnidade = useMemo(() => {
    return unitsInScope.map((u) => {
      const aulasU = scopeClasses.filter((c) => c.unitId === u.id);
      const idsU = new Set(aulasU.map((c) => c.id));
      const presU = scopeAttendance.filter((a) => idsU.has(a.classId));
      return {
        id: u.id,
        name: u.name,
        aulas: aulasU.length,
        presencas: presU.length,
        media: aulasU.length ? (presU.length / aulasU.length).toFixed(1) : "0",
      };
    });
  }, [unitsInScope, scopeClasses, scopeAttendance]);

  const studentsInScope = studentId
    ? students.filter((s) => s.id === studentId)
    : students.filter((s) => !unitId || s.unitId === unitId);
  const porAluno = useMemo(() => {
    return studentsInScope
      .map((s) => {
        const aulasOferecidas = scopeClasses.filter((c) => c.unitId === s.unitId).length;
        const presencas = attendance.filter((a) => a.studentId === s.id && scopeClassIds.has(a.classId)).length;
        const taxa = aulasOferecidas ? Math.round((presencas / aulasOferecidas) * 100) : 0;
        return {
          id: s.id,
          name: s.name,
          unitName: units.find((u) => u.id === s.unitId)?.name || "—",
          aulasOferecidas,
          presencas,
          taxa,
        };
      })
      .sort((a, b) => b.taxa - a.taxa);
  }, [studentsInScope, units, scopeClasses, scopeClassIds, attendance]);

  function limparFiltros() {
    setMesAno("");
    setUnitId("");
    setTeacherId("");
    setStudentId("");
  }

  if (classes.length === 0) {
    return <EmptyState text="Ainda não há aulas registradas. Os números aparecem aqui assim que a primeira presença for marcada." />;
  }

  return (
    <div className="flex flex-col gap-6 max-w-4xl">
      <div style={{ background: C.bgPanel, borderColor: C.line }} className="border rounded-md p-4 grid grid-cols-2 sm:grid-cols-4 gap-3">
        <div className="col-span-2 sm:col-span-1">
          <input
            type="month"
            value={mesAno}
            onChange={(e) => setMesAno(e.target.value)}
            style={{ background: C.bgRaised, borderColor: C.line, color: mesAno ? C.text : C.textFaint }}
            className="border rounded-md px-3 py-2 text-sm outline-none w-full"
          />
        </div>
        <div className="col-span-2 sm:col-span-1">
          <Select value={unitId} onChange={setUnitId} placeholder="Todas as unidades" options={units.map((u) => ({ value: u.id, label: u.name }))} />
        </div>
        <div className="col-span-2 sm:col-span-1">
          <Select value={teacherId} onChange={setTeacherId} placeholder="Todos os professores" options={teachers.map((t) => ({ value: t.id, label: t.name }))} />
        </div>
        <div className="col-span-2 sm:col-span-1">
          <Select value={studentId} onChange={setStudentId} placeholder="Todos os alunos" options={studentOptions.map((s) => ({ value: s.id, label: s.name }))} />
        </div>
        {hasFilters && (
          <button onClick={limparFiltros} style={{ color: C.textDim }} className="col-span-2 sm:col-span-4 text-xs text-left underline underline-offset-2 hover:opacity-80">
            Limpar filtros
          </button>
        )}
      </div>

      <div className="grid grid-cols-3 gap-3">
        <StatCard label="Total de aulas" value={totalAulas} />
        <StatCard label="Total de presenças" value={totalPresencas} />
        <StatCard label="Média por aula" value={mediaPorAula} />
      </div>

      {porUnidade.length > 0 && (
        <div>
          <SectionTitle>Por unidade</SectionTitle>
          <div style={{ background: C.bgPanel, borderColor: C.line }} className="border rounded-md overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr style={{ color: C.textFaint, borderColor: C.lineSoft }} className="border-b text-left text-xs">
                  <th className="font-medium px-4 py-2">Unidade</th>
                  <th className="font-medium px-4 py-2 text-right">Aulas</th>
                  <th className="font-medium px-4 py-2 text-right">Presenças</th>
                  <th className="font-medium px-4 py-2 text-right">Média/aula</th>
                </tr>
              </thead>
              <tbody>
                {porUnidade.map((u) => (
                  <tr key={u.id} style={{ borderColor: C.lineSoft }} className="border-b last:border-0">
                    <td style={{ color: C.text }} className="px-4 py-2.5">{u.name}</td>
                    <td style={{ color: C.textDim }} className="px-4 py-2.5 text-right">{u.aulas}</td>
                    <td style={{ color: C.textDim }} className="px-4 py-2.5 text-right">{u.presencas}</td>
                    <td style={{ color: C.brass }} className="px-4 py-2.5 text-right font-semibold">{u.media}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <div>
        <SectionTitle>Por aluno — taxa de frequência</SectionTitle>
        <div style={{ background: C.bgPanel, borderColor: C.line }} className="border rounded-md overflow-hidden">
          {porAluno.length === 0 && (
            <div style={{ color: C.textFaint }} className="text-sm px-4 py-6 text-center">
              Nenhum aluno nesse recorte.
            </div>
          )}
          {porAluno.length > 0 && (
            <table className="w-full text-sm">
              <thead>
                <tr style={{ color: C.textFaint, borderColor: C.lineSoft }} className="border-b text-left text-xs">
                  <th className="font-medium px-4 py-2">Aluno</th>
                  <th className="font-medium px-4 py-2">Unidade</th>
                  <th className="font-medium px-4 py-2 text-right">Aulas oferecidas</th>
                  <th className="font-medium px-4 py-2 text-right">Presenças</th>
                  <th className="font-medium px-4 py-2 text-right">Taxa</th>
                </tr>
              </thead>
              <tbody>
                {porAluno.map((r) => (
                  <tr key={r.id} style={{ borderColor: C.lineSoft }} className="border-b last:border-0">
                    <td style={{ color: C.text }} className="px-4 py-2.5">{r.name}</td>
                    <td style={{ color: C.textDim }} className="px-4 py-2.5">{r.unitName}</td>
                    <td style={{ color: C.textDim }} className="px-4 py-2.5 text-right">{r.aulasOferecidas}</td>
                    <td style={{ color: C.textDim }} className="px-4 py-2.5 text-right">{r.presencas}</td>
                    <td className="px-4 py-2.5 text-right">
                      <TaxaBar taxa={r.taxa} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}
function TaxaBar({ taxa }) {
  const color = taxa >= 70 ? C.oliveBright : taxa >= 40 ? C.brass : C.red;
  return (
    <div className="flex items-center justify-end gap-2">
      <div style={{ background: C.bgRaised }} className="w-16 h-1.5 rounded-full overflow-hidden">
        <div style={{ background: color, width: `${taxa}%` }} className="h-full" />
      </div>
      <span style={{ color }} className="font-semibold text-xs w-9 text-right">
        {taxa}%
      </span>
    </div>
  );
}

function StatCard({ label, value }) {
  return (
    <div style={{ background: C.bgPanel, borderColor: C.line }} className="border rounded-md p-4">
      <div style={{ color: C.textFaint }} className="text-xs mb-1">
        {label}
      </div>
      <div style={{ color: C.text }} className="text-2xl font-bold tabular-nums">
        {value}
      </div>
    </div>
  );
}

function SectionTitle({ children }) {
  return (
    <div style={{ color: C.text }} className="text-sm font-semibold mb-2">
      {children}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Cadastros
// ---------------------------------------------------------------------------
function CadastrosPage({ units, setUnits, teachers, setTeachers, students, setStudents, persistCadastros }) {
  const [tab, setTab] = useState("unidades");

  function addUnit(name) {
    const next = [...units, { id: uid(), name }];
    setUnits(next);
    persistCadastros(next, teachers, students);
  }
  function removeUnit(id) {
    const next = units.filter((u) => u.id !== id);
    setUnits(next);
    persistCadastros(next, teachers, students);
  }
  function addTeacher(name) {
    const next = [...teachers, { id: uid(), name }];
    setTeachers(next);
    persistCadastros(units, next, students);
  }
  function removeTeacher(id) {
    const next = teachers.filter((t) => t.id !== id);
    setTeachers(next);
    persistCadastros(units, next, students);
  }
  function addStudent(name, cpf, unitId, periodo) {
    const next = [...students, { id: uid(), name, cpf, unitId, periodo }];
    setStudents(next);
    persistCadastros(units, teachers, next);
  }
  function removeStudent(id) {
    const next = students.filter((s) => s.id !== id);
    setStudents(next);
    persistCadastros(units, teachers, next);
  }

  return (
    <div className="max-w-2xl">
      <div style={{ borderColor: C.line }} className="border-b flex gap-1 mb-4">
        {[
          ["unidades", "Unidades"],
          ["professores", "Professores"],
          ["alunos", "Alunos"],
        ].map(([key, label]) => (
          <button
            key={key}
            onClick={() => setTab(key)}
            style={{
              color: tab === key ? C.text : C.textFaint,
              borderColor: tab === key ? C.red : "transparent",
            }}
            className="text-sm px-3 py-2 border-b-2 -mb-px font-medium"
          >
            {label}
          </button>
        ))}
      </div>

      {tab === "unidades" && (
        <SimpleList
          items={units}
          onAdd={addUnit}
          onRemove={removeUnit}
          placeholder="Nome da unidade"
        />
      )}

      {tab === "professores" && (
        <SimpleList
          items={teachers}
          onAdd={addTeacher}
          onRemove={removeTeacher}
          placeholder="Nome do professor"
        />
      )}

      {tab === "alunos" && (
        <StudentList units={units} students={students} onAdd={addStudent} onRemove={removeStudent} />
      )}
    </div>
  );
}

function SimpleList({ items, onAdd, onRemove, placeholder }) {
  const [name, setName] = useState("");
  return (
    <div className="flex flex-col gap-3">
      <form
        onSubmit={(e) => {
          e.preventDefault();
          if (!name.trim()) return;
          onAdd(name.trim());
          setName("");
        }}
        className="flex gap-2"
      >
        <input
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder={placeholder}
          style={{ background: C.bgRaised, borderColor: C.line, color: C.text }}
          className="border rounded-md px-3 py-2 text-sm outline-none flex-1"
        />
        <button
          type="submit"
          style={{ background: C.red, color: C.text }}
          className="rounded-md px-3 flex items-center justify-center"
        >
          <Plus size={16} />
        </button>
      </form>
      <div style={{ background: C.bgPanel, borderColor: C.line }} className="border rounded-md overflow-hidden">
        {items.length === 0 && (
          <div style={{ color: C.textFaint }} className="text-sm px-4 py-6 text-center">
            Nada cadastrado ainda.
          </div>
        )}
        {items.map((it) => (
          <div
            key={it.id}
            style={{ borderColor: C.lineSoft }}
            className="border-b last:border-0 flex items-center justify-between px-4 py-2.5"
          >
            <span style={{ color: C.text }} className="text-sm">
              {it.name}
            </span>
            <button onClick={() => onRemove(it.id)} style={{ color: C.textFaint }}>
              <Trash2 size={15} />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

function StudentList({ units, students, onAdd, onRemove }) {
  const [name, setName] = useState("");
  const [cpf, setCpf] = useState("");
  const [unitId, setUnitId] = useState("");
  const [periodo, setPeriodo] = useState("");

  return (
    <div className="flex flex-col gap-3">
      <form
        onSubmit={(e) => {
          e.preventDefault();
          if (!name.trim() || !cpf.trim() || !unitId || !periodo) return;
          onAdd(name.trim(), cpf.trim(), unitId, periodo);
          setName("");
          setCpf("");
        }}
        className="flex flex-col gap-2"
      >
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Nome do aluno"
            style={{ background: C.bgRaised, borderColor: C.line, color: C.text }}
            className="border rounded-md px-3 py-2 text-sm outline-none"
          />
          <input
            value={cpf}
            onChange={(e) => setCpf(e.target.value)}
            placeholder="CPF"
            style={{ background: C.bgRaised, borderColor: C.line, color: C.text }}
            className="border rounded-md px-3 py-2 text-sm outline-none"
          />
          <Select
            value={unitId}
            onChange={setUnitId}
            placeholder="Unidade"
            options={units.map((u) => ({ value: u.id, label: u.name }))}
          />
          <Select
            value={periodo}
            onChange={setPeriodo}
            placeholder="Período"
            options={PERIODS.map((p) => ({ value: p, label: p }))}
          />
        </div>
        <button
          type="submit"
          style={{ background: C.red, color: C.text }}
          className="rounded-md px-3 py-2 flex items-center justify-center gap-1.5 text-sm font-medium"
        >
          <Plus size={16} />
          Adicionar aluno
        </button>
      </form>
      {units.length === 0 && (
        <div style={{ color: C.textFaint }} className="text-xs">
          Cadastre uma unidade antes de adicionar alunos.
        </div>
      )}
      <div style={{ background: C.bgPanel, borderColor: C.line }} className="border rounded-md overflow-hidden">
        {students.length === 0 && (
          <div style={{ color: C.textFaint }} className="text-sm px-4 py-6 text-center">
            Nenhum aluno cadastrado ainda.
          </div>
        )}
        {students.map((s) => (
          <div
            key={s.id}
            style={{ borderColor: C.lineSoft }}
            className="border-b last:border-0 flex items-center justify-between px-4 py-2.5"
          >
            <div>
              <div style={{ color: C.text }} className="text-sm">
                {s.name}
              </div>
              <div style={{ color: C.textFaint }} className="text-xs">
                {units.find((u) => u.id === s.unitId)?.name || "sem unidade"}
                {s.periodo ? ` · ${s.periodo}` : ""}
                {s.cpf ? ` · ${s.cpf}` : ""}
              </div>
            </div>

            <button onClick={() => onRemove(s.id)} style={{ color: C.textFaint }}>
              <Trash2 size={15} />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
